package college.quarry;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.Path;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static college.quarry.Values.*;
import static college.quarry.Database.*;
class QuarryServiceTest {
 @TempDir Path temp;
 Database db;QuarryService service;AuthService auth;
 @BeforeEach void setup()throws Exception{db=new Database(temp.toString(),true);service=new QuarryService();auth=new AuthService();}
 Map<String,Object> person(String username)throws Exception{return db.transaction(c->first(c,"SELECT id,name,username,role FROM users WHERE username=?",username));}
 Object call(String username,String method,String path,Map<String,Object>b)throws Exception{var u=person(username);return db.transaction(c->service.route(c,method+" /api"+path,u,b));}
 @SuppressWarnings("unchecked") Map<String,Object> map(Object o){return (Map<String,Object>)o;}
 long stock()throws Exception{return db.transaction(c->scalar(c,"SELECT qty_kg FROM stone WHERE id=1"));}
 Map<String,Object> order(String customer,String code)throws Exception{return map(call(customer,"POST","/orders",obj("stone_id",1,"qty","1.250","card",code)));}
 @Test void moneyUsesIntegerCentsAndDecimalRounding(){assertEquals(112500,amount(1250,90000));assertEquals(101,amount(1000,101));assertEquals(1250,kg("1.250"));assertThrows(ApiError.class,()->kg("1.0001"));}
 @Test void confirmedOrderReducesStockAndGetsInvoice()throws Exception{long initial=stock();var r=order("customer","1234");assertNotNull(r.get("invoice"));assertEquals(initial-1250,stock());}
 @Test void paymentFailureIsRetainedWithoutStockChange()throws Exception{long initial=stock();var r=order("customer","0000");assertEquals(true,r.get("paymentFailed"));assertEquals(initial,stock());assertEquals("Payment Failed",db.transaction(c->first(c,"SELECT status FROM orders WHERE id=?",r.get("orderId"))).get("status"));}
 @Test void cancellationRestoresStockOnlyOnce()throws Exception{long initial=stock();var r=order("customer","1234");call("customer","POST","/orders/cancel",obj("id",r.get("orderId")));assertEquals(initial,stock());assertThrows(ApiError.class,()->call("customer","POST","/orders/cancel",obj("id",r.get("orderId"))));assertEquals(initial,stock());}
 @Test void customersCannotReadOrCancelAnotherCustomersInvoice()throws Exception{var r=order("customer","1234");ApiError e=assertThrows(ApiError.class,()->call("customer2","GET","/invoice",obj("id",r.get("orderId"))));assertEquals(404,e.status);assertThrows(ApiError.class,()->call("customer2","POST","/orders/cancel",obj("id",r.get("orderId"))));assertTrue(((List<?>)call("customer2","GET","/orders",obj())).isEmpty());}
 @Test void dispatchPreventsCancellation()throws Exception{var r=order("customer","1234");call("store","POST","/dispatch",obj("order_id",r.get("orderId"),"plate","TEST-1","weighed","1.250"));assertThrows(ApiError.class,()->call("customer","POST","/orders/cancel",obj("id",r.get("orderId"))));}
 @Test void excessiveDispatchLoadIsRejected()throws Exception{var r=order("customer","1234");assertThrows(ApiError.class,()->call("store","POST","/dispatch",obj("order_id",r.get("orderId"),"plate","TEST-1","weighed","2")));}
 @Test void productionSafetyAndQualityControlInventory()throws Exception{long initial=stock();assertThrows(ApiError.class,()->call("worker","POST","/prod",obj("stone_id",1,"tons",2,"quality","Pass","safe",false)));call("worker","POST","/prod",obj("stone_id",1,"tons",2,"quality","Fail","safe",true));assertEquals(initial,stock());call("worker","POST","/prod",obj("stone_id",1,"tons",2,"quality","Pass","safe",true));assertEquals(initial+2000,stock());assertTrue(((List<?>)call("worker2","GET","/prod",obj())).isEmpty());}
 @Test void singleManagerAndDuplicateUserAreRejected()throws Exception{assertThrows(ApiError.class,()->call("admin","POST","/users",obj("name","Another manager","username","manager2","password","NewPass@123","role","Manager")));assertThrows(ApiError.class,()->call("admin","POST","/users",obj("name","Duplicate","username","CUSTOMER","password","NewPass@123","role","Customer")));}
 @Test void attendanceAlternatesAndUsesWorkerId()throws Exception{assertThrows(ApiError.class,()->call("worker","POST","/attendance",obj("event","Check-out")));call("worker","POST","/attendance",obj("event","Check-in"));assertThrows(ApiError.class,()->call("worker","POST","/attendance",obj("event","Check-in")));call("worker","POST","/attendance",obj("event","Check-out"));assertTrue(((List<?>)call("worker2","GET","/attendance",obj())).isEmpty());}
 @Test void workerIncidentsArePrivateAndManagerResolves()throws Exception{call("worker","POST","/incidents",obj("severity","High","details","Test report"));assertTrue(((List<?>)call("worker2","GET","/incidents",obj())).isEmpty());long id=db.transaction(c->scalar(c,"SELECT id FROM incidents LIMIT 1"));call("manager","POST","/incidents/resolve",obj("id",id));assertEquals(1L,db.transaction(c->scalar(c,"SELECT resolved FROM incidents WHERE id=?",id)).longValue());}
 @Test void maintenanceUsesKnownMachineAndNonnegativeCost()throws Exception{assertThrows(ApiError.class,()->call("manager","POST","/mlog",obj("machine_id",1,"issue","Test","cost","-1")));call("manager","POST","/mlog",obj("machine_id",1,"issue","Test","cost","10.50"));assertEquals(1050L,db.transaction(c->scalar(c,"SELECT cost_cents FROM maintenance LIMIT 1")).longValue());}
 @Test void roleChecksAndRollbackWork()throws Exception{assertEquals(403,assertThrows(ApiError.class,()->call("worker","GET","/users",obj())).status);long initial=stock();assertThrows(ApiError.class,()->db.transaction(c->{update(c,"UPDATE stone SET qty_kg=0 WHERE id=1");throw ApiError.bad("rollback test");}));assertEquals(initial,stock());}
 @Test void revenueExcludesCancelledAndFailedOrders()throws Exception{var a=order("customer","1234");order("customer","0000");var b=order("customer","1234");call("customer","POST","/orders/cancel",obj("id",b.get("orderId")));assertNotNull(a.get("invoice"));assertEquals(112500L,db.transaction(c->scalar(c,"SELECT SUM(amount_cents) FROM orders WHERE status IN ('Paid','Dispatched')")).longValue());}
 @Test void loginLogoutAndPasswordChange()throws Exception{var login=db.transaction(c->auth.login(c,obj("username","customer","password","Customer@123"),"test"));String t=(String)login.get("token");var u=db.transaction(c->auth.user(c,t));db.transaction(c->auth.changePassword(c,u,obj("currentPassword","Customer@123","newPassword","Changed@123")));assertThrows(ApiError.class,()->db.transaction(c->auth.user(c,t)));var again=db.transaction(c->auth.login(c,obj("username","customer","password","Changed@123"),"test"));String t2=(String)again.get("token");auth.logout(t2);assertThrows(ApiError.class,()->db.transaction(c->auth.user(c,t2)));}
 @Test void reportsRequireManagementRole()throws Exception{var u=person("worker");assertThrows(ApiError.class,()->db.transaction(c->service.report(c,"stock",u)));var manager=person("manager");assertEquals(4,db.transaction(c->service.report(c,"stock",manager)).size());}
 @Test void loginThrottlesFailedAttempts()throws Exception{for(int i=0;i<10;i++)assertThrows(ApiError.class,()->db.transaction(c->auth.login(c,obj("username","noaccount","password","wrong"),"throttle-test")));assertEquals(429,assertThrows(ApiError.class,()->db.transaction(c->auth.login(c,obj("username","customer","password","Customer@123"),"throttle-test"))).status);}
}
